import hashlib

def double_sha256(data):
    return hashlib.sha256(hashlib.sha256(data).digest()).digest()

def merkle_root(txns):
    if not txns:
        return None
    hashes = [double_sha256(tx.encode()) for tx in txns]
    while len(hashes) > 1:
        if len(hashes) % 2 == 1:
            hashes.append(hashes[-1])
        new_hashes = []
        for i in range(0, len(hashes), 2):
            concat = hashes[i] + hashes[i+1]
            new_hashes.append(double_sha256(concat))
        hashes = new_hashes
    return hashes[0].hex()

root = merkle_root(['Alice pays Bob 5', 'Bob pays Carol 3', 'Carol pays Dave 2'])
print(root)
